-- STAGING ONLY 491: bind exact Gmail UID635 archive after terminal receipt and advance paused replay floor to UID636.
BEGIN;SELECT pg_advisory_xact_lock(hashtextextended('pdc-staging-491-uid635-archive-and-paused-floor',0));DO $g$ BEGIN IF current_user<>'postgres' OR (SELECT count(*) FROM public.pdc_staging_environment_sentinel WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd')<>1 OR to_regclass('public.pdc_production_environment_sentinel') IS NOT NULL OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260827040000' AND name='490_finalize_uid635_terminal_import') OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version~'^[0-9]{14}$' AND version>'20260827040000') OR (SELECT count(*) FROM public.pdc_uid635_terminal_import_receipts_490 WHERE action_key='uid635-terminal-receipt-backed-import' AND archive_eligible AND NOT archived AND production_untouched)<>1 OR (SELECT count(*) FROM public.pdc_staging_replay_fences_466 WHERE fence_key='email:Inbox' AND uidvalidity=1 AND denied_through=631 AND first_eligible=632)<>1 OR EXISTS(SELECT 1 FROM public.pdc_email_monitor_pilot WHERE enabled OR automatic_rule_application OR automatic_authenticated_jobcards OR outbound_email_enabled) OR EXISTS(SELECT 1 FROM public.monitored_mailboxes WHERE active) OR EXISTS(SELECT 1 FROM public.pdc_monitor_stage_activation_writers WHERE active AND revoked_at IS NULL) OR (SELECT count(*) FROM public.ai_email_intake WHERE provider_uid='imap_uid:636' AND status='needs_review' AND linked_vehicle_id IS NULL)<>1 THEN RAISE EXCEPTION 'PDC_491_TARGET_HEAD_SCOPE_OR_CONTAINMENT_MISMATCH' USING errcode='55000';END IF;END $g$;CREATE TABLE public.pdc_email_replay_fences_491(fence_key text PRIMARY KEY CHECK(fence_key='uidvalidity-1-uid-635-stock-13000775'),folder text NOT NULL CHECK(folder='Inbox'),uidvalidity bigint NOT NULL CHECK(uidvalidity=1),provider_uid bigint NOT NULL CHECK(provider_uid=635),source_hash text NOT NULL CHECK(source_hash='a7d78113b6a01a0965409d8ed88f803ae8920aaa2ca733db8739ec13a81262b4'),stock_number text NOT NULL CHECK(stock_number='13000775'),job_card_number text NOT NULL CHECK(job_card_number='J139125494'),reason text NOT NULL CHECK(reason='Terminal receipt-backed staging import archived from Inbox; exact source permanently denied from replay'),created_by uuid NOT NULL CHECK(created_by='8a83b715-8d79-4b0e-95b2-02b55da6e8d7'),created_by_email text NOT NULL CHECK(created_by_email='craig.watson@broometoyota.com.au'),created_at timestamptz NOT NULL DEFAULT clock_timestamp());ALTER TABLE public.pdc_email_replay_fences_491 ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.pdc_email_replay_fences_491 FROM public,anon,authenticated,service_role;INSERT INTO public.pdc_email_replay_fences_491(fence_key,folder,uidvalidity,provider_uid,source_hash,stock_number,job_card_number,reason,created_by,created_by_email) VALUES('uidvalidity-1-uid-635-stock-13000775','Inbox',1,635,'a7d78113b6a01a0965409d8ed88f803ae8920aaa2ca733db8739ec13a81262b4','13000775','J139125494','Terminal receipt-backed staging import archived from Inbox; exact source permanently denied from replay','8a83b715-8d79-4b0e-95b2-02b55da6e8d7','craig.watson@broometoyota.com.au');ALTER TABLE public.pdc_staging_replay_fences_466 DISABLE TRIGGER USER;UPDATE public.pdc_staging_replay_fences_466 SET denied_through=635,first_eligible=636 WHERE fence_key='email:Inbox' AND uidvalidity=1 AND denied_through=631 AND first_eligible=632;ALTER TABLE public.pdc_staging_replay_fences_466 ENABLE TRIGGER USER;UPDATE public.pdc_email_monitor_pilot SET enabled=false,minimum_uid=636,automatic_rule_application=false,automatic_authenticated_jobcards=false,outbound_email_enabled=false,updated_at=clock_timestamp() WHERE singleton;CREATE TABLE public.pdc_uid635_archive_receipts_491(receipt_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),action_key text NOT NULL UNIQUE CHECK(action_key='archive-uid635-after-terminal-receipt'),terminal_receipt_id uuid NOT NULL CHECK(terminal_receipt_id='924cd6b4-eab3-45a7-b3c9-6173c0746c7e') REFERENCES public.pdc_uid635_terminal_import_receipts_490(receipt_id),folder text NOT NULL CHECK(folder='Inbox'),uidvalidity bigint NOT NULL CHECK(uidvalidity=1),provider_uid bigint NOT NULL CHECK(provider_uid=635),inbox_before boolean NOT NULL CHECK(inbox_before),inbox_after boolean NOT NULL CHECK(NOT inbox_after),unrelated_uid636_before boolean NOT NULL CHECK(unrelated_uid636_before),unrelated_uid636_after boolean NOT NULL CHECK(unrelated_uid636_after),archive_basis text NOT NULL CHECK(archive_basis='terminal receipt-backed success with authoritative vehicle and 22-operation read-back'),scheduler_sha256 text NOT NULL CHECK(scheduler_sha256='1a18c53c25be514b7a8b3a444d6cb20b5d6ef7fa99b6930dda37dcd7b61f17f6'),processor_sha256 text NOT NULL CHECK(processor_sha256='dfd493de92a86b92b2eea72763d5a067ac1092c4ddda1a2e29af39e4713adfba'),client_sha256 text NOT NULL CHECK(client_sha256='d19ef949179e9c96f2feb4d4795f1c42d040d54c15bf5e6615369354ad55f63e'),recurring_monitor_enabled boolean NOT NULL CHECK(NOT recurring_monitor_enabled),production_untouched boolean NOT NULL CHECK(production_untouched),created_at timestamptz NOT NULL DEFAULT clock_timestamp());ALTER TABLE public.pdc_uid635_archive_receipts_491 ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.pdc_uid635_archive_receipts_491 FROM public,anon,authenticated,service_role;INSERT INTO public.pdc_uid635_archive_receipts_491(action_key,terminal_receipt_id,folder,uidvalidity,provider_uid,inbox_before,inbox_after,unrelated_uid636_before,unrelated_uid636_after,archive_basis,scheduler_sha256,processor_sha256,client_sha256,recurring_monitor_enabled,production_untouched) SELECT 'archive-uid635-after-terminal-receipt',receipt_id,'Inbox',1,635,true,false,true,true,'terminal receipt-backed success with authoritative vehicle and 22-operation read-back','1a18c53c25be514b7a8b3a444d6cb20b5d6ef7fa99b6930dda37dcd7b61f17f6','dfd493de92a86b92b2eea72763d5a067ac1092c4ddda1a2e29af39e4713adfba','d19ef949179e9c96f2feb4d4795f1c42d040d54c15bf5e6615369354ad55f63e',false,true FROM public.pdc_uid635_terminal_import_receipts_490 WHERE action_key='uid635-terminal-receipt-backed-import';DO $p$ BEGIN IF (SELECT count(*) FROM public.pdc_staging_replay_fences_466 WHERE fence_key='email:Inbox' AND uidvalidity=1 AND denied_through=635 AND first_eligible=636)<>1 OR (SELECT count(*) FROM public.pdc_email_replay_fences_491 WHERE provider_uid=635 AND stock_number='13000775')<>1 OR (SELECT count(*) FROM public.pdc_uid635_archive_receipts_491 WHERE inbox_before AND NOT inbox_after AND unrelated_uid636_after AND NOT recurring_monitor_enabled AND production_untouched)<>1 OR EXISTS(SELECT 1 FROM public.pdc_email_monitor_pilot WHERE enabled OR automatic_rule_application OR automatic_authenticated_jobcards OR outbound_email_enabled) THEN RAISE EXCEPTION 'PDC_491_ARCHIVE_FENCE_OR_CONTAINMENT_POSTCONDITION_FAILED' USING errcode='55000';END IF;END $p$;INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20260827041000','491_bind_uid635_archive_paused_floor',ARRAY['Record exact Gmail Inbox UID635 archive only after terminal receipt-backed success','Verify unrelated UID636 remained in Inbox and nonterminal review','Advance denied-through replay floor to UID635 and first eligible UID to 636','Bind paused scheduler/parser/client hashes without resuming recurring automation','Production untouched']);COMMIT;
